using System;using Ossastra.CharacterCore;
class CoordinationTests{static void Main(){var type=typeof(Health).Assembly.GetType("Ossastra.CharacterCore.ActionAdmissionLedger");if(type==null)throw new Exception("missing shared action admission transaction");dynamic ledger=Activator.CreateInstance(type);var id=Guid.NewGuid();int cancelled=0,paid=0;Func<bool> commit=()=>{cancelled++;paid++;return true;};if(ledger.TryCommit(id,"stale-life",commit))throw new Exception("invalid request committed");if(cancelled!=0||paid!=0)throw new Exception("rejected request changed active action or resources");if(!ledger.TryCommit(id,(string)null,commit)||ledger.TryCommit(id,(string)null,commit))throw new Exception("accepted request must commit exactly once");if(cancelled!=1||paid!=1)throw new Exception("duplicate payment");Console.WriteLine("4 admission transaction contracts passed");}}
